import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track cooperation and defection counts for each opponent
        self.interactions = {}  # opponent_id -> {'C': int, 'D': int, 'coop': int, 'defect': int}
        # Track reputation: for each agent, count of cooperative vs defecting acts observed
        self.reputation = {}  # agent_id -> {'coop': int, 'defect': int}
        # Track how often I cooperated with each opponent
        self.my_coop = {}  # opponent_id -> count of times I cooperated
        self.my_defect = {}  # opponent_id -> count of times I defected
        # Track my own total cooperation rate
        self.my_total_coop = 0
        self.my_total_actions = 0
        # Track current opponent
        self._ctx_opponent_id = None
        # Track round number for possible time-based adjustments (optional)
        self.round_num = 0

    def decide(self) -> bool:
        # Get opponent
        opp = self._ctx_opponent_id
        if opp is None:
            return True  # Default cooperate if no opponent (shouldn't happen)

        # Initialize state for this opponent if needed
        if opp not in self.interactions:
            self.interactions[opp] = {'C': 0, 'D': 0, 'coop': 0, 'defect': 0}
        opp_stats = self.interactions[opp]
        my_interactions = opp_stats['C'] + opp_stats['D']  # total times I've interacted with this opponent

        # Compute opponent's cooperation rate from observed interactions (their actions)
        opp_total_actions = opp_stats['coop'] + opp_stats['defect']
        if opp_total_actions == 0:
            # No observations yet: use reputation from third-party observations
            # If no data, default to cooperative
            opp_coop_rate = 0.5  # neutral
        else:
            opp_coop_rate = opp_stats['coop'] / opp_total_actions

        # Also consider my own history with this opponent
        my_total_with_opp = self.my_coop.get(opp, 0) + self.my_defect.get(opp, 0)
        if my_total_with_opp > 0:
            my_coop_rate = self.my_coop.get(opp, 0) / my_total_with_opp
        else:
            my_coop_rate = 0.5

        # Strategy: Tit-for-tat with forgiveness and reputation-based adjustment
        # Start cooperative, then mirror opponent's previous action if known,
        # but be forgiving occasionally.

        # If we have interacted before, use last action? But we only have counts, not sequence.
        # Instead: if opponent has defected often, defect; if cooperated often, cooperate.
        # Use a threshold based on cooperation rate.

        # Simple rule: cooperate if opponent's cooperation rate > 0.5 or we haven't interacted much
        if opp_total_actions == 0:
            # No direct observations, but maybe reputation from others
            # Use global reputation if available
            rep = self.reputation.get(opp, None)
            if rep and (rep['coop'] + rep['defect']) > 0:
                rep_rate = rep['coop'] / (rep['coop'] + rep['defect'])
                # If reputation is very bad, defect; otherwise cooperate
                return rep_rate >= 0.4
            else:
                return True  # No info, cooperate
        else:
            # Have direct observations
            # Be more cooperative if opponent is cooperative, but defect if they defect often
            # Add forgiveness: if opponent was previously cooperative but just defected, still cooperate sometimes
            # Since we don't have sequence, use rate.
            if opp_coop_rate >= 0.5:
                # Opponent is cooperative overall, cooperate
                return True
            else:
                # Opponent is mostly defective, but add noise/forgiveness
                # Use a random chance to cooperate based on how many times they've defected
                # If they have defected many times, be more likely to defect
                # But allow some cooperation to test them
                defect_count = opp_stats['defect']
                coop_count = opp_stats['coop']
                total = defect_count + coop_count
                # If they have defected more than cooperated, defect with high probability
                # But occasionally cooperate to test
                if total == 0:
                    return True
                # Probability to cooperate = 0.3 if they are mostly defectors, 0.7 if mixed
                if defect_count > coop_count:
                    prob = 0.3
                else:
                    prob = 0.7
                # Use random, but deterministic seed? We can use random but it's fine.
                return random.random() < prob

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for donor and recipient (third-party observation)
        # For donor
        if donor_id not in self.reputation:
            self.reputation[donor_id] = {'coop': 0, 'defect': 0}
        if donor_action == 'cooperate':
            self.reputation[donor_id]['coop'] += 1
        else:
            self.reputation[donor_id]['defect'] += 1

        # For recipient (they also chose an action)
        if recipient_id not in self.reputation:
            self.reputation[recipient_id] = {'coop': 0, 'defect': 0}
        if recipient_action == 'cooperate':
            self.reputation[recipient_id]['coop'] += 1
        else:
            self.reputation[recipient_id]['defect'] += 1

        # If I am involved in this interaction, update my personal history with the opponent
        if donor_id == self.agent_id:
            # I am donor, recipient is opponent
            opp = recipient_id
            if opp not in self.interactions:
                self.interactions[opp] = {'C': 0, 'D': 0, 'coop': 0, 'defect': 0}
            # Update my action
            if donor_action == 'cooperate':
                self.my_coop[opp] = self.my_coop.get(opp, 0) + 1
                self.interactions[opp]['C'] += 1
            else:
                self.my_defect[opp] = self.my_defect.get(opp, 0) + 1
                self.interactions[opp]['D'] += 1
            # Update opponent's action (they are recipient)
            if recipient_action == 'cooperate':
                self.interactions[opp]['coop'] += 1
            else:
                self.interactions[opp]['defect'] += 1
            # Update my total
            self.my_total_actions += 1
            if donor_action == 'cooperate':
                self.my_total_coop += 1
        elif recipient_id == self.agent_id:
            # I am recipient, donor is opponent
            opp = donor_id
            if opp not in self.interactions:
                self.interactions[opp] = {'C': 0, 'D': 0, 'coop': 0, 'defect': 0}
            # Update my action (as recipient)
            if recipient_action == 'cooperate':
                self.my_coop[opp] = self.my_coop.get(opp, 0) + 1
                self.interactions[opp]['C'] += 1
            else:
                self.my_defect[opp] = self.my_defect.get(opp, 0) + 1
                self.interactions[opp]['D'] += 1
            # Update opponent's action (they are donor)
            if donor_action == 'cooperate':
                self.interactions[opp]['coop'] += 1
            else:
                self.interactions[opp]['defect'] += 1
            # Update my total
            self.my_total_actions += 1
            if recipient_action == 'cooperate':
                self.my_total_coop += 1
        # If not involved, just reputation updated above

