class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_history = {}
        self.interaction_count = {}
        self.generation = 0
        self.round = 0
        self.last_decide = True
        self.opponent_id = None
        self.self_coop_count = 0
        self.self_defect_count = 0
        self.total_self_actions = 0
        self.trust_threshold = 50.0
        self.defection_penalty = 20.0
        self.coop_bonus = 5.0
        self.forgiveness_factor = 0.1
        self.reputation_init = 50.0
        self.epsilon = 0.1
        self.recent_actions = {}  # agent_id -> list of recent actions (True/False) for reciprocal strategy

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True
        self.opponent_id = opponent

        if self.round < 10:
            if random.random() < self.epsilon * 0.5:
                return random.choice([True, False])

        rep_opp = self.reputation.get(opponent, self.reputation_init)
        coop_count = 0
        defect_count = 0
        if opponent in self.cooperation_history:
            for act in self.cooperation_history[opponent]:
                if act:
                    coop_count += 1
                else:
                    defect_count += 1
        total = coop_count + defect_count
        if total > 0:
            coop_ratio = coop_count / total
            score = 0.6 * rep_opp + 0.4 * (coop_ratio * 100)
        else:
            score = rep_opp

        if total >= 5:
            if coop_ratio < 0.3:
                score -= self.defection_penalty
            elif coop_ratio > 0.7:
                score += self.coop_bonus

        # Change: Add a reciprocal component based on opponent's last action toward us
        if opponent in self.recent_actions and self.recent_actions[opponent]:
            last_action = self.recent_actions[opponent][-1]
            if last_action:
                score += 5.0  # Reward if they cooperated last time
            else:
                score -= 10.0  # Penalize if they defected last time

        if score >= self.trust_threshold:
            return True
        else:
            if score >= self.trust_threshold - self.forgiveness_factor * 100:
                if random.random() < 0.2:
                    return True
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_reputation_from_action(donor_id, donor_action)
        self._update_reputation_from_action(recipient_id, recipient_action)

        if donor_id == self.agent_id:
            self._record_action(recipient_id, donor_action == 'cooperate')
            if donor_action == 'cooperate':
                self.self_coop_count += 1
            else:
                self.self_defect_count += 1
            self.total_self_actions += 1
        if recipient_id == self.agent_id:
            self._record_action(donor_id, recipient_action == 'cooperate')
            if recipient_action == 'cooperate':
                self.self_coop_count += 1
            else:
                self.self_defect_count += 1
            self.total_self_actions += 1

        self.interaction_count[donor_id] = self.interaction_count.get(donor_id, 0) + 1
        self.interaction_count[recipient_id] = self.interaction_count.get(recipient_id, 0) + 1

        # New: Track recent actions toward self specifically
        if donor_id == self.agent_id:
            # We acted toward recipient, record what we did
            self.recent_actions[recipient_id] = self.recent_actions.get(recipient_id, [])
            self.recent_actions[recipient_id].append(donor_action == 'cooperate')
            if len(self.recent_actions[recipient_id]) > 5:
                self.recent_actions[recipient_id].pop(0)
        if recipient_id == self.agent_id:
            # Opponent acted toward us, record what they did
            self.recent_actions[donor_id] = self.recent_actions.get(donor_id, [])
            self.recent_actions[donor_id].append(recipient_action == 'cooperate')
            if len(self.recent_actions[donor_id]) > 5:
                self.recent_actions[donor_id].pop(0)

    def _update_reputation_from_action(self, agent_id: int, action: str) -> None:
        current = self.reputation.get(agent_id, self.reputation_init)
        if action == 'cooperate':
            current += 2.0
        else:
            current -= 5.0
        current = max(0.0, min(100.0, current))
        self.reputation[agent_id] = current

    def _record_action(self, agent_id: int, action: bool) -> None:
        if agent_id not in self.cooperation_history:
            self.cooperation_history[agent_id] = []
        if len(self.cooperation_history[agent_id]) >= 20:
            self.cooperation_history[agent_id].pop(0)
        self.cooperation_history[agent_id].append(action)

