import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputations = {}
        self.interaction_history = []
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.defected_against_me = {}
        self.cooperated_with_me = {}
        self.round_num = 0
        self.generation = 0
        self.last_opponent = None
        self.last_my_action = None
        self.last_opp_action = None
        # New: track memory of recent interactions for each opponent
        self.recent_interactions = {}  # opp_id -> list of (my_action, opp_action)

    def _get_reputation(self, agent_id: int) -> float:
        return self.reputations.get(agent_id, 0.5)

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        opp_rep = self._get_reputation(opponent)

        # Base on reputation and personal bias
        personal_bias = 0.5
        if opponent in self.cooperated_with_me:
            coop_count = self.cooperated_with_me[opponent]
            def_count = self.defected_against_me.get(opponent, 0)
            total = coop_count + def_count
            if total > 0:
                personal_bias = coop_count / total

        combined = 0.6 * opp_rep + 0.4 * personal_bias

        # New: Check recent interactions for patterns
        if opponent in self.recent_interactions:
            recent = self.recent_interactions[opponent]
            # If opponent defected in last 2 interactions, be more suspicious
            if len(recent) >= 2 and all(action == 'defect' for _, action in recent[-2:]):
                combined -= 0.1
            # If opponent cooperated in last 3 interactions, be more trusting
            if len(recent) >= 3 and all(action == 'cooperate' for _, action in recent[-3:]):
                combined += 0.1

        noise = random.uniform(-0.05, 0.05)
        combined += noise

        return combined >= 0.5

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Reputation updates (same as parent)
        donor_delta = 0.0
        if donor_action == 'cooperate':
            donor_delta = 0.1
        else:
            if recipient_action == 'cooperate':
                donor_delta = -0.15
            else:
                donor_delta = -0.05

        recipient_delta = 0.0
        if recipient_action == 'cooperate':
            recipient_delta = 0.1
        else:
            if donor_action == 'cooperate':
                recipient_delta = -0.15
            else:
                recipient_delta = -0.05

        old_rep = self.reputations.get(donor_id, 0.5)
        new_rep = max(0.0, min(1.0, old_rep + donor_delta))
        self.reputations[donor_id] = new_rep

        old_rep = self.reputations.get(recipient_id, 0.5)
        new_rep = max(0.0, min(1.0, old_rep + recipient_delta))
        self.reputations[recipient_id] = new_rep

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            if opp_action == 'cooperate':
                self.cooperated_with_me[opp_id] = self.cooperated_with_me.get(opp_id, 0) + 1
            else:
                self.defected_against_me[opp_id] = self.defected_against_me.get(opp_id, 0) + 1

            if my_action == 'cooperate':
                self.my_coop_count += 1
            else:
                self.my_defect_count += 1

            self.interaction_history.append((donor_id, donor_action, recipient_id, recipient_action))

            # Update recent interactions memory
            if opp_id not in self.recent_interactions:
                self.recent_interactions[opp_id] = []
            self.recent_interactions[opp_id].append((my_action, opp_action))
            # Keep only last 5 interactions
            if len(self.recent_interactions[opp_id]) > 5:
                self.recent_interactions[opp_id] = self.recent_interactions[opp_id][-5:]

            self.last_opponent = opp_id
            self.last_my_action = my_action
            self.last_opp_action = opp_action
        else:
            pass

