        self.defect_counts = {}
        self.my_coop = 0
        self.my_defect = 0
        self.opponent_history = {}
        self.my_actions = {}
        self.round_count = 0
        self.gen_count = 0
        self.trust_factor = 0.5
        self.exploited = 0
        self.exploited_opponents = set()
        self.nice_rewarded = 0
        self.last_opponent_action = None
        self.last_my_action = None
        # Additional memory: track recent actions for both self and opponents in a sliding window
        self.recent_self_actions = []
        self.recent_opponent_actions = []
        self.window_size = 10
        # Track opponent-specific recent actions for better pattern detection
        self.opponent_recent = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.round_count += 1
        if opponent is None:
            return True

        coop = self.coop_counts.get(opponent, 0)
        defect = self.defect_counts.get(opponent, 0)
        total = coop + defect
        if total == 0:
            rep_score = 0.5
        else:
            rep_score = coop / total

        my_hist = self.my_actions.get(opponent, [])
        opp_hist = self.opponent_history.get(opponent, [])

        # New: Use recent opponent actions to detect patterns (e.g., alternating)
        recent_opp = self.opponent_recent.get(opponent, [])
        if len(recent_opp) >= 2:
            last_two = recent_opp[-2:]
            # If they alternate between cooperate and defect, they might be unpredictable
            if last_two[0] != last_two[1]:
                # If they have a decent reputation, cooperate; otherwise defect
                if rep_score > 0.5:
                    return True
                else:
                    return False

        if len(my_hist) == 0:
            if rep_score > 0.6:
                return True
            elif rep_score < 0.4:
                return False
            else:
                return (self.agent_id + self.round_count) % 2 == 0

        last_opp_act = opp_hist[-1] if opp_hist else None
        last_my_act = my_hist[-1] if my_hist else None

        if last_my_act == 'cooperate' and last_opp_act == 'defect':
            self.exploited += 1
            self.exploited_opponents.add(opponent)
            # New: More forgiving if opponent has high reputation overall
            if rep_score > 0.75:
                return True
            if self.exploited % 5 == 0:
                return True
            else:
                return False
        if last_opp_act == 'cooperate':
            return True
        if last_opp_act == 'defect' and last_my_act == 'defect':
            if rep_score < 0.3:
                return False
            else:
                return (self.round_count % 3) == 0
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        if donor_action == 'cooperate':
            self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + 1
        else:
            self.defect_counts[donor_id] = self.defect_counts.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + 1
        else:
            self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + 1

        if donor_id == self.agent_id:
            self.my_coop += 1 if donor_action == 'cooperate' else 0
            self.my_defect += 1 if donor_action == 'defect' else 0
            self.my_actions.setdefault(recipient_id, []).append(donor_action)
            self.last_my_action = donor_action
            self.opponent_history.setdefault(recipient_id, []).append(recipient_action)
            self.last_opponent_action = recipient_action
            # Update recent self actions
            self.recent_self_actions.append(donor_action)
            if len(self.recent_self_actions) > self.window_size:
                self.recent_self_actions.pop(0)
            # Update opponent recent for this specific opponent
            opp_recent = self.opponent_recent.setdefault(recipient_id, [])
            opp_recent.append(recipient_action)
            if len(opp_recent) > self.window_size:
                opp_recent.pop(0)
        elif recipient_id == self.agent_id:
            self.my_coop += 1 if recipient_action == 'cooperate' else 0
            self.my_defect += 1 if recipient_action == 'defect' else 0
            self.my_actions.setdefault(donor_id, []).append(recipient_action)
            self.last_my_action = recipient_action
            self.opponent_history.setdefault(donor_id, []).append(donor_action)
            self.last_opponent_action = donor_action
            self.recent_self_actions.append(recipient_action)
            if len(self.recent_self_actions) > self.window_size:
                self.recent_self_actions.pop(0)
            opp_recent = self.opponent_recent.setdefault(donor_id, [])
            opp_recent.append(donor_action)
            if len(opp_recent) > self.window_size:
                opp_recent.pop(0)
        # Third-party: also update recent opponent actions for the observed pair
        else:
            # Update recent for donor
            donor_recent = self.opponent_recent.setdefault(donor_id, [])
            donor_recent.append(donor_action)
            if len(donor_recent) > self.window_size:
                donor_recent.pop(0)
            # Update recent for recipient
            recipient_recent = self.opponent_recent.setdefault(recipient_id, [])
            recipient_recent.append(recipient_action)
            if len(recipient_recent) > self.window_size:
                recipient_recent.pop(0)

