        self.my_defect_count = 0
        self.defected_against_me = {}
        self.cooperated_with_me = {}
        self.round_num = 0
        self.generation = 0
        self.last_opponent = None
        self.last_my_action = None
        self.last_opp_action = None
        # Track recent defections against me to enable forgiveness/retaliation
        self.recent_defections = {}  # agent_id -> list of recent round numbers
        self.round_counter = 0

    def _get_reputation(self, agent_id: int) -> float:
        return self.reputations.get(agent_id, 0.5)

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        opp_rep = self._get_reputation(opponent)

        # Personal bias based on direct interactions
        personal_bias = 0.5
        if opponent in self.cooperated_with_me:
            coop_count = self.cooperated_with_me[opponent]
            def_count = self.defected_against_me.get(opponent, 0)
            total = coop_count + def_count
            if total > 0:
                personal_bias = coop_count / total

        # Recent defection penalty: if opponent has defected against me in the last 3 rounds, penalize
        recent_def_penalty = 0.0
        if opponent in self.recent_defections:
            recent_defs = [r for r in self.recent_defections[opponent] if self.round_counter - r <= 3]
            if recent_defs:
                recent_def_penalty = 0.1 * len(recent_defs)

        # Combined score with penalty
        combined = 0.6 * opp_rep + 0.4 * personal_bias - recent_def_penalty

        # Add noise
        combined += random.uniform(-0.05, 0.05)

        # Also, if opponent has defected against me more than 5 times total, strongly defect
        total_defs = self.defected_against_me.get(opponent, 0)
        if total_defs > 5:
            combined -= 0.3

        return combined >= 0.5

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.round_counter += 1

        # Update reputations with more nuance
        donor_delta = 0.0
        if donor_action == 'cooperate':
            donor_delta = 0.1
        else:
            if recipient_action == 'cooperate':
                donor_delta = -0.15
            else:
                donor_delta = -0.05

        recipient_delta = 0.0
        if recipient_action == 'cooperate':
            recipient_delta = 0.1
        else:
            if donor_action == 'cooperate':
                recipient_delta = -0.15
            else:
                recipient_delta = -0.05

        # Update reputations
        old_rep = self.reputations.get(donor_id, 0.5)
        new_rep = max(0.0, min(1.0, old_rep + donor_delta))
        self.reputations[donor_id] = new_rep

        old_rep = self.reputations.get(recipient_id, 0.5)
        new_rep = max(0.0, min(1.0, old_rep + recipient_delta))
        self.reputations[recipient_id] = new_rep

        # Handle self-play
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            if opp_action == 'cooperate':
                self.cooperated_with_me[opp_id] = self.cooperated_with_me.get(opp_id, 0) + 1
            else:
                self.defected_against_me[opp_id] = self.defected_against_me.get(opp_id, 0) + 1
                # Track recent defection
                if opp_id not in self.recent_defections:
