        total = coop + defect
        if total == 0:
            rep_score = 0.5
        else:
            recent_opp = self.opponent_recent.get(opponent, [])
            if recent_opp:
                recent_coop = sum(1 for a in recent_opp if a == 'cooperate')
                recent_total = len(recent_opp)
                recent_rep = recent_coop / recent_total
                rep_score = self.recent_weight * recent_rep + (1 - self.recent_weight) * (coop / total)
            else:
                rep_score = coop / total

        my_hist = self.my_actions.get(opponent, [])
        opp_hist = self.opponent_history.get(opponent, [])

