                self.defected_against_me[opp_id] = self.defected_against_me.get(opp_id, 0) + 1
                # Track recent defection
                if opp_id not in self.recent_defections:
                    self.recent_defections[opp_id] = []
                self.recent_defections[opp_id].append(self.round_counter)

            if my_action == 'cooperate':
                self.my_coop_count += 1
            else:
                self.my_defect_count += 1

            self.interaction_history.append((donor_id, donor_action, recipient_id, recipient_action))
            self.last_opponent = opp_id
            self.last_my_action = my_action
            self.last_opp_action = opp_action

